    fun buildStage1SystemPrompt(text: String, lang: String = "ja", k: Int = 5): String {
        val pool = if (lang == "en") EXAMPLE_POOL_EN else EXAMPLE_POOL_JA
        val scored = pool.map { example ->
            example.keywords.count { keyword -> text.contains(keyword, ignoreCase = true) } to example
        }.sortedByDescending { it.first }
        val initial = scored.take(k)
        val selected = if (initial.all { it.first == 0 }) pool.take(k).map { 0 to it } else initial
        val examples = if (lang == "en") {
            selected.joinToString("\n\n") { (_, example) -> "Input: ${example.input}\nOutput: ${example.output}" }
        } else {
            selected.joinToString("\n\n") { (_, example) -> "入力: ${example.input}\n出力: ${example.output}" }
        }
        val prefix = if (lang == "en") STAGE1_PROMPT_PREFIX_EN else STAGE1_PROMPT_PREFIX_JA
        val sectionHeader = if (lang == "en") "# Examples\n\n" else "# 変換例\n\n"
        return prefix + "\n\n" + sectionHeader + examples
    }

    fun sanitizePlacementWords(ddl: String): String {
        var sanitized = ddl
        sanitized = sanitized.replace(Regex("ランダムに", RegexOption.IGNORE_CASE), "画面全体に点々と")
        sanitized = sanitized.replace(Regex("ランダムな", RegexOption.IGNORE_CASE), "画面全体に点々とした")
        sanitized = sanitized.replace(Regex("ランダム", RegexOption.IGNORE_CASE), "画面全体に点々")
        sanitized = sanitized.replace(Regex("\\brandomly\\b", RegexOption.IGNORE_CASE), "dotted across the whole canvas")
        sanitized = sanitized.replace(Regex("\\brandom\\b", RegexOption.IGNORE_CASE), "all-over")
        return sanitized
    }
